package com.mealmate.order;import org.springframework.beans.factory.annotation.*;import org.springframework.kafka.core.*;import org.springframework.stereotype.*;import org.springframework.web.client.RestTemplate;import java.util.*;@Service class OrderService{final OrderRepository r;final KafkaTemplate<String,Object> k;final RestTemplate w=new RestTemplate();final String url,token;OrderService(OrderRepository x,KafkaTemplate<String,Object> y,@Value("${services.availability-url}")String u,@Value("${internal.token}")String t){r=x;k=y;url=u;token=t;}OrderModel create(CreateRequest q,String key){var z=r.findByIdempotencyKey(key);if(z.isPresent())return z.get();var o=r.save(new OrderModel(q.customerId(),q.restaurantId(),q.failPayment(),q.failDeliveryAssignment(),key));try{var h=new org.springframework.http.HttpHeaders();h.set("X-Internal-Token",token);w.postForEntity(url+"/availability/reservations",new org.springframework.http.HttpEntity<>(q.items(),h),Void.class);k.send("food-order-events",o.getId().toString(),new Event(UUID.randomUUID().toString(),"FoodOrderCreated",o.getId(),q.failPayment(),q.failDeliveryAssignment()));}catch(Exception e){o.setStatus(OrderStatus.REJECTED);r.save(o);}return o;}OrderModel get(UUID id){return r.findById(id).orElseThrow();}OrderModel cancel(UUID id){var o=get(id);o.setStatus(OrderStatus.CANCELLED);return r.save(o);}record Event(String eventId,String type,UUID orderId,boolean failPayment,boolean failDeliveryAssignment){}}
